// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: actor is the caller who will invoke setOwner, newOwner is the candidate owner passed in
    function testFuzz_property(address actor, address newOwner) public {
        // avoid the zero address being special- but keep domain wide
        vm.assume(actor != address(0));

        // Ensure actor is the current owner by performing the call as the deploying address (setUp deploys c from this address)
        // The deployer is address(this) in setUp; ensure actor is that deployer so actor must equal address(this)
        // Instead, we will make the deployer (address(this)) transfer ownership to actor first using the valid setOwner
        // so that actor becomes owner before the test call. First, from deployer (this), set owner to actor.
        // deployer is address(this) already, so call directly
        bool ok;
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference contract must allow the deployer (initial owner) to set owner to actor
        assertTrue(ok);

        // Now fuzzed actor (which is now owner) calls setOwner(newOwner)
        vm.prank(actor);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after an owner calls setOwner(newOwner), the contract's owner getter must equal newOwner.
        // This holds for the reference implementation for all inputs; the mutant (which assigns msg.sender) will break
        // whenever newOwner != actor (the caller).
        assertTrue(c.owner() == newOwner);
    }
}

