pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: actor who will attempt to call setOwner, and the target newOwner to set
    function testFuzz_property(address caller, address newOwner) public {
        // Keep addresses within wide admissible domain (non-zero for clarity, but not required)
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Record the current owner according to the contract
        address originalOwner = c.owner();

        // Make the fuzzed caller attempt to call setOwner(newOwner)
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: only the original owner is allowed to change owner.
        // Therefore, after the call completes, the owner must be unchanged unless the caller was the original owner.
        // This is expressed as: if caller != originalOwner then c.owner() == originalOwner; else caller may have changed it.
        // Single assertion that the reference satisfies for all inputs and the mutant violates for some inputs.
        assertTrue( (caller == originalOwner) || (c.owner() == originalOwner) );
    }
}

