import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter: the address to set as new owner
    function testFuzz_property(address newOwner) public {
        // keep address wide but avoid zero-address triviality (still allowed; reference should accept it)
        // no restrictive assumptions so fuzzer can find counterexample for mutant

        // caller must be the current owner to call setOwner; by default setUp deployed c with msg.sender = address(this)
        // but in Foundry tests, the test contract is the deployer, so address(this) is the owner.
        // we need to call setOwner as the owner: use vm.prank to make the call from the test contract's deployer address
        // However, since the test contract is the deployer and calls are from this contract, we can call directly.

        // Call setOwner as the owner
        bool ok;
        try c.setOwner(newOwner) returns (bool) { ok = true; } catch { ok = false; }

        // The universal property to assert: after a successful call, c.owner() == newOwner.
        // For the reference C this holds for all inputs; the mutant that sets owner = address(0) will violate it for many newOwner values.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted (shouldn't for the correct contract when caller is owner), assert false to fail the test on reference
            // But to keep the single assertion reading c as required, we assert that the call succeeded by checking owner unchanged equals address(this)
            // This branch should not be taken for the reference; still assert a property that the reference satisfies for all admissible inputs.
            assertTrue(c.owner() == address(this));
        }
    }
}

