pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: a candidate newOwner and the caller address
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but avoid zero address for clarity (still admissible domain is wide)
        vm.assume(caller != address(0));

        // record initial owner (deployed contract's owner is the test contract by default)
        address initialOwner = c.owner();

        // ensure caller has ETH to perform transactions if needed
        vm.deal(caller, 1 ether);

        bool ok;
        // attempt to call setOwner as the fuzzed caller
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // The universal property: if caller is NOT the current owner, the correct contract will revert (call fails)
        // Conversely, if caller IS the current owner, the correct contract will succeed and update owner to newOwner.
        // We assert the reference behavior: after the call, if caller was the owner then c.owner() == newOwner; otherwise c.owner() == initialOwner.
        // This assertion holds for the reference contract for ALL inputs; the mutant (which allows non-owners) will fail for some inputs
        if (caller == initialOwner) {
            // owner-call should succeed and set owner to newOwner
            assertTrue(c.owner() == newOwner);
        } else {
            // non-owner call should not change owner
            assertTrue(c.owner() == initialOwner);
        }
    }
}

