pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an EOA that will be the original owner (ownerAddr) and a different EOA attacker
    // The fuzzer will pick addresses; we will bound them to non-zero and ensure they differ.
    function testFuzz_property(address ownerAddr, address attackerEOA) public {
        // keep inputs admissible and wide
        vm.assume(ownerAddr != address(0));
        vm.assume(attackerEOA != address(0));
        vm.assume(ownerAddr != attackerEOA);

        // Fund both EOAs so they can send transactions
        vm.deal(ownerAddr, 1 ether);
        vm.deal(attackerEOA, 1 ether);

        // Make ownerAddr the contract owner by having it deploy a fresh C and then transferring ownership
        // but spec requires c is deployed in setUp() by this test runner; current owner is address(this) deployer
        // So first, transfer ownership from deployer (address(this)) to ownerAddr by calling setOwner as the deployer
        // The deployer is the current owner, so this call should succeed on the reference contract
        bool ok;
        try c.setOwner(ownerAddr) { ok = true; } catch { ok = false; }
        // ensure the initial transfer to ownerAddr succeeded (both reference and mutant allow deployer to change owner)
        assertTrue(ok);
        assertTrue(c.owner() == ownerAddr);

        // Deploy a relayer contract that, when called by attackerEOA, will call c.setOwner(attackerEOA) from the relayer
        Relayer relayer = new Relayer(c);

        // attackerEOA calls the relayer which in turn calls c.setOwner(attackerEOA)
        // For the reference contract (uses msg.sender), this should revert/fail because relayer != ownerAddr
        // For the mutant (uses tx.origin), tx.origin == attackerEOA and if ownerAddr == attackerEOA it would succeed,
        // but we ensured ownerAddr != attackerEOA, so mutant will incorrectly allow the relayer to change owner because tx.origin is attackerEOA

        vm.prank(attackerEOA);
        // call relayer which forwards to c
        relayer.relaySetOwner(attackerEOA);

        // Exactly one assertion: in the correct contract, after the relayed call, owner remains ownerAddr
        assertTrue(c.owner() == ownerAddr);
    }
}

// minimal relayer that calls c.setOwner on behalf of msg.sender
contract Relayer {
    C public c;
    constructor(C _c) { c = _c; }
    function relaySetOwner(address newOwner) external {
        // forward call to c; msg.sender here will be this contract
        c.setOwner(newOwner);
    }
}

